#include <bits/stdc++.h>
using namespace std;
typedef long long ll;

int main() {
    string s;
    cin >> s;
    int n = s.size();
    vector<ll> dp(n + 1, 0);
    for (int end = 1; end <= n; end++) {
        // Last run s[start..end-1] can be one color iff it holds at most one fixed letter.
        char color = 0;
        ll best = 0;
        for (int start = end - 1; start >= 0; start--) {
            char c = s[start];
            if (c != '.') {
                if (color && c != color) break;
                color = c;
            }
            ll len = end - start;
            best = max(best, dp[start] + len * (len + 1) / 2);
        }
        dp[end] = best;
    }
    printf("%lld\n", dp[n]);
}

import java.io.*;

public class Main {
    static byte[] buf;
    static int pos;

    static void skip() {
        while (pos < buf.length && buf[pos] <= ' ') pos++;
    }

    static String next() {
        skip();
        int s = pos;
        while (pos < buf.length && buf[pos] > ' ') pos++;
        return new String(buf, s, pos - s);
    }

    static long nextLong() {
        skip();
        boolean neg = buf[pos] == '-';
        if (neg) pos++;
        long r = 0;
        while (pos < buf.length && buf[pos] > ' ') r = r * 10 + (buf[pos++] - '0');
        return neg ? -r : r;
    }

    static int nextInt() {
        return (int) nextLong();
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        char[] s = next().toCharArray();
        int n = s.length;
        long[] dp = new long[n + 1];
        for (int end = 1; end <= n; end++) {
            // Last run s[start..end-1] can be one color iff it holds at most one fixed letter.
            char color = 0;
            long best = 0;
            for (int start = end - 1; start >= 0; start--) {
                char c = s[start];
                if (c != '.') {
                    if (color != 0 && c != color) break;
                    color = c;
                }
                long len = end - start;
                best = Math.max(best, dp[start] + len * (len + 1) / 2);
            }
            dp[end] = best;
        }
        System.out.println(dp[n]);
    }
}

